// Sample data: nine weeks of ChatGPT (Chat and Work) and Codex activity for
// the Acme Corp people, generated by the OpenAI stand-in's generator
// (scripts/openai-mock/data.mjs) and written through the OpenAI sync's own
// code, so the rows are exactly what a real ChatGPT Enterprise export gives:
// prompts, replies, hourly costs, Codex turns and actions, skills and
// connectors. No OpenAI key is needed or saved.
//
// Then, as the Hub would: ChatGPT conversation times and Codex session
// figures. And, as the Claude sample does, a grade for every ChatGPT prompt
// and Codex session (tier and kind of work, deepening over the nine weeks),
// so Work Pulse, Developer Pulse, Spend Review and Use Cases show ChatGPT and
// Codex without a Claude API key. With a key the Hub grades new work itself.
//
// Run by scripts/demo/load.cjs. Safe to run again: the generator's ids are
// fixed and every write skips what is already there.
import { sql } from 'drizzle-orm';
import { buildEvents, buildFiles } from '../openai-mock/data.mjs';
import { importOpenAiFiles } from '../../lib/openai/sync';
import { rollupChatgptSessionTime } from '../../lib/pulse/chatgpt-session-time';
import { rollupCodeSessionStats } from '../../lib/pulse/code/aggregator';
import { getTypedClient } from '../../lib/db/client';
import { addSessionMatch, refreshWeekFromJunction } from '../../lib/usecases/weeks';
import { recomputeWeekImpact } from '../../lib/usecases/impact-rollup';
import { weekStart } from '../../lib/pulse/period';

const DAYS = 63;
const MODEL = 'claude-haiku-4-5-20251001';
// The Claude sample's kinds of work (01-organisation.cjs), so both vendors read alike.
const TASK_TYPES = ['analysis', 'structured_report', 'synthesis', 'summarisation', 'basic_drafting', 'template_population', 'process_substitution'];
const CODE_TASK_TYPES = ['bug_investigation', 'feature_build', 'code_review', 'documentation', 'refactor'];

/** A ChatGPT prompt's kind of work from its words, as a classifier would read it; otherwise one at random. */
function taskTypeFor(text: string): string {
  const t = text.toLowerCase();
  if (/summar|recap|tl;?dr|key points/.test(t)) return 'summarisation';
  if (/draft|email|write|reply|letter|post/.test(t)) return 'basic_drafting';
  if (/report|brief|memo|pack|deck/.test(t)) return 'structured_report';
  if (/analys|compare|forecast|trend|variance|why /.test(t)) return 'analysis';
  if (/template|fill in|populate|form/.test(t)) return 'template_population';
  if (/combine|pull together|across|synthes/.test(t)) return 'synthesis';
  return TASK_TYPES[Math.floor(Math.random() * TASK_TYPES.length)];
}

/** A JSON-array column, read as a list of strings (stored as text). */
function list(v: unknown): string[] {
  let x: unknown = v;
  if (typeof v === 'string') { try { x = JSON.parse(v); } catch { return []; } }
  return Array.isArray(x) ? x.filter((s): s is string => typeof s === 'string') : [];
}

/** Tier 1-3, deeper as the nine weeks go on (as the Claude sample grows). */
function tierAt(at: number, startS: number, nowS: number): number {
  const trend = Math.min(1, Math.max(0, (at - startS) / (nowS - startS)));
  const depth = 0.25 + 0.45 * trend;
  const deep = 0.15 + 0.35 * trend;
  return Math.random() < depth ? (Math.random() < deep ? 3 : 2) : 1;
}

(async () => {
  const nowMs = Date.now();
  const nowS = Math.floor(nowMs / 1000);
  const startS = nowS - DAYS * 86400;
  const { events } = buildEvents({ nowMs, days: DAYS, horizonHours: 0 });
  // Files in the order the export would list them, oldest first.
  const files = (buildFiles(events) as Array<{ endMs: number; body: string }>)
    .filter((f) => f.endMs <= nowMs)
    .sort((a, b) => a.endMs - b.endMs)
    .map((f) => f.body.split('\n').filter(Boolean).map((line) => JSON.parse(line) as unknown));
  const stats = await importOpenAiFiles(files, nowS);
  const prompts = Object.values(stats.prompts as Record<string, number>).reduce((a, b) => a + b, 0);
  console.log(`${files.length} export files, ${prompts} ChatGPT and Codex prompts.`);

  // ChatGPT conversation times (each rollup covers the 30 days before the time given).
  let times = 0;
  for (const back of [0, 30, 60]) times += await rollupChatgptSessionTime(nowS - back * 86400);
  console.log(`${times} ChatGPT conversation times.`);

  // Codex session figures: every session, not only those since the Hub last looked.
  const client = await getTypedClient();
  const raw = client as unknown as { execute: (q: unknown) => Promise<{ rows: Array<Record<string, unknown>> }> };
  await raw.execute(sql`DELETE FROM config WHERE key = 'code_aggregator_last_run'`);
  const sessions = await rollupCodeSessionStats();
  console.log(`${sessions} Codex session figures.`);

  // Grades for ChatGPT prompts and Codex sessions not yet graded.
  const gptPrompts = (await raw.execute(sql`
    SELECT m.id, m.user_id, m.occurred_at, COALESCE(m.content_full, m.content_preview, '') AS text
      FROM cowork_messages m
     WHERE m.source IN ('chatgpt_chat', 'chatgpt_work') AND m.message_type = 'cowork_user_message' AND m.user_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM pulse_classifications pc WHERE pc.cowork_message_id = m.id)`)).rows;
  for (const p of gptPrompts) {
    const at = Number(p.occurred_at);
    await raw.execute(sql`
      INSERT INTO pulse_classifications (cowork_message_id, user_id, tier, task_type, classifier_confidence, classifier_model, classified_at)
      VALUES (${String(p.id)}, ${String(p.user_id)}, ${tierAt(at, startS, nowS)}, ${taskTypeFor(String(p.text))}, ${0.85 + Math.random() * 0.12}, ${MODEL}, ${at + 30})
      ON CONFLICT (cowork_message_id) DO NOTHING`);
  }
  const codexSessions = (await raw.execute(sql`
    SELECT s.session_id, s.user_id, s.last_at,
           (SELECT COALESCE(SUM(a.commit_count), 0) FROM codex_actions a WHERE a.session_id = s.session_id) AS commits
      FROM code_session_stats s
     WHERE s.session_id LIKE 'codex:%' AND s.user_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM code_session_classifications c WHERE c.session_id = s.session_id)`)).rows;
  for (const s of codexSessions) {
    const last = Number(s.last_at);
    const shipped = Number(s.commits) > 0;
    const tier = shipped ? (Math.random() < 0.5 ? 3 : 2) : tierAt(last, startS, nowS);
    await raw.execute(sql`
      INSERT INTO code_session_classifications (session_id, user_id, work_type, tier, confidence, classifier_model, status, classified_at)
      VALUES (${String(s.session_id)}, ${String(s.user_id)}, ${CODE_TASK_TYPES[Math.floor(Math.random() * CODE_TASK_TYPES.length)]}, ${tier}, ${0.75 + Math.random() * 0.15}, ${MODEL}, 'classified', ${last})
      ON CONFLICT (session_id) DO NOTHING`);
  }
  console.log(`${gptPrompts.length} ChatGPT prompts and ${codexSessions.length} Codex sessions graded.`);

  // Use case matches, as the Claude sample ships its own: a ChatGPT or Codex
  // session matches a sample use case of the person's department (or one for
  // everyone) when one of its prompts carries one of the use case's clue
  // words, and the use case covers that kind of work (ChatGPT as Work, Codex
  // as Code). With a Claude API key the Hub's session judge reads the work itself.
  const ucs = (await raw.execute(sql`
    SELECT id, departments, surfaces, keywords FROM use_cases WHERE status <> 'archived'`)).rows
    .map((u) => ({
      id: String(u.id),
      departments: list(u.departments),
      surfaces: list(u.surfaces),
      keywords: list(u.keywords).map((k) => k.toLowerCase()).filter((k) => k.length >= 4),
    }))
    .filter((u) => u.keywords.length > 0);
  const sessionsToMatch = (await raw.execute(sql`
    SELECT m.session_id, m.user_id, m.source, MIN(m.occurred_at) AS first_at,
           string_agg(lower(COALESCE(m.content_full, m.content_preview, '')), ' ') AS text,
           MAX(COALESCE(NULLIF(TRIM(u.department), ''), NULLIF(TRIM(au.department), ''))) AS dept
      FROM cowork_messages m
      LEFT JOIN users u ON u.id = m.user_id
      LEFT JOIN admin_users au ON au.linked_cowork_user_id = m.user_id
     WHERE m.source IN ('chatgpt_chat', 'chatgpt_work', 'codex') AND m.user_id IS NOT NULL
       AND m.message_type IN ('cowork_user_message', 'code_user_message')
     GROUP BY m.session_id, m.user_id, m.source`)).rows;
  const touched = new Set<string>();
  let matched = 0;
  for (const s of sessionsToMatch) {
    const surface = s.source === 'codex' ? 'code' : 'cowork';
    const dept = s.dept == null ? null : String(s.dept);
    const text = String(s.text ?? '');
    for (const u of ucs) {
      if (u.departments.length > 0 && (dept === null || !u.departments.includes(dept))) continue;
      if (u.surfaces.length > 0 && !u.surfaces.includes(surface)) continue;
      if (!u.keywords.some((k) => text.includes(k))) continue;
      const week = weekStart(Number(s.first_at));
      await addSessionMatch(u.id, week, String(s.user_id), String(s.session_id));
      touched.add(`${u.id}|${week}`);
      matched++;
    }
  }
  for (const key of touched) {
    const [id, week] = key.split('|');
    await refreshWeekFromJunction(id, Number(week));
    await recomputeWeekImpact(id, Number(week));
  }
  console.log(`${matched} ChatGPT and Codex sessions matched to use cases, ${touched.size} use case weeks recounted.`);
  process.exit(0);
})().catch((e) => { console.error(e); process.exit(1); });
